package com.bank.agefilter;

import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class AvgAgeAboveDemo {
    private static final Logger log = Logger.getLogger("AgeFilter");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", "IT", 50),
            new Employee("Amit", "IT", 40),      // IT avg 45 → above 35
            new Employee("Priya", "Sales", 30),
            new Employee("Neha", "Sales", 28));  // Sales avg 29 → not above
        AgeFilterService service = new AgeFilterService();

        log.info(() -> "Depts avg age > 35: " + service.deptsAverageAgeAbove(staff, 35));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final String department;
    private final int age;
    Employee(String name, String department, int age) {
            this.name = name;
            this.department = department
            this.age = age;
    }
    String getDepartment() { return department; }
    int getAge() { return age; }
}

// ─── Would be in service/AgeFilterService.java ───
class AgeFilterService {
    List<String> deptsAverageAgeAbove(List<Employee> staff, double threshold) {
        Map<String, Double> avgAge = staff.stream()
            .collect(groupingBy(Employee::getDepartment,
                averagingDouble(Employee::getAge)));        // avg age per dept
        return avgAge.entrySet().stream()
            .filter(e -> e.getValue() > threshold)           // HAVING avg > 35
            .map(Map.Entry::getKey)
            .sorted()                                        // stable presentation
            .toList();
    }
}
